import csv


def column_stats(path):
    with open(path, encoding="utf-8", newline="") as f:
        rows = list(csv.DictReader(f))
    if not rows:
        return {}
    columns = [k for k in rows[0] if all(_is_number(r[k]) for r in rows)]
    stats = {}
    for col in columns:
        values = [float(r[col]) for r in rows]
        stats[col] = {
            "mean": sum(values) / len(values),
            "min": min(values),
            "max": max(values),
        }
    return stats


def _is_number(text):
    try:
        float(text)
        return True
    except (TypeError, ValueError):
        return False
